bash -c 'echo "=== 1. Syntax check all Python files ===" && find "$TARGET_DIR" -name "*.py" | xargs python3 -m py_compile && echo "Syntax: OK" && echo "" && echo "=== 2. Interface check ===" && python3 -c '\''import ast, os; 
def params(p):
    tree = ast.parse(open(p).read())
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == "run_agent":
            return [a.arg for a in node.args.args]
    return None
old = params(os.path.join(os.environ["ORIGINAL_DIR"], "run_buggy.py"))
new = params(os.path.join(os.environ["TARGET_DIR"], "run_buggy.py"))
assert new == old, f"run_agent parameters changed: {old} -> {new}"
print("run_agent interface: OK", new)'\'' && echo "" && echo "=== 3. Diff summary ===" && diff -rq --exclude="*.pyc" --exclude="__pycache__" "$ORIGINAL_DIR" "$TARGET_DIR" 2>/dev/null | grep "^Files" || echo "(no file differences)" && echo "" && echo "=== All checks passed ==="

